def calculate_heads_down(n):
    N = 2 * n + 1
    flip_counts = {i: 0 for i in range(N)}

    # The k-th flip targets coin P_k, where P_k = k*(k-1)/2 mod N
    # k runs from 1 to N (2n+1)

    for k in range(1, N + 1):
        # P_k = k*(k-1)//2
        position = (k * (k - 1) // 2) % N
        flip_counts[position] += 1

    heads_down = 0
    for count in flip_counts.values():
        if count % 2 != 0:
            heads_down += 1

    return heads_down

results = {}
for n in range(1, 5):
    results[n] = calculate_heads_down(n)

print(f"Calculated results for n=1 to 4: {results}")

def solve_flips(n):
    C = 2 * n + 1
    positions = []
    for k in range(1, C + 1):
        # P'_k = (k(k+1)/2 - 1) mod C
        position = (k * (k + 1) // 2 - 1) % C
        positions.append(position)

    counts = {}
    for pos in positions:
        counts[pos] = counts.get(pos, 0) + 1

    heads_down = 0
    for pos, count in counts.items():
        if count % 2 != 0:
            heads_down += 1

    return heads_down

# Test n=3
n_test = 3
result = solve_flips(n_test)
print(f"For n={n_test}, the total number of heads down is: {result}")

